    def top(self,yaw):return Rotation.from_euler('z',yaw).as_matrix()@np.diag([1.,-1.,-1.])
    def ik(self,p,R,q0=None):
        self.kd.qpos[:]=self.s.data.qpos
        q=self.s.data.qpos[self.qids].copy() if q0 is None else q0.copy()
        for _ in range(100):
            self.kd.qpos[self.qids]=q
            mujoco.mj_kinematics(self.m,self.kd); mujoco.mj_comPos(self.m,self.kd)
            ep=np.asarray(p)-self.kd.site_xpos[self.sid]
            er=Rotation.from_matrix(R@self.kd.site_xmat[self.sid].reshape(3,3).T).as_rotvec()
