            mujoco.mj_jacSite(self.m,self.kd,self.jp,self.jr,self.sid)
            J=np.vstack([self.jp[:,self.vids],.4*self.jr[:,self.vids]])
            e=np.r_[ep,.4*er]
            inv=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,np.eye(6))
            dq=inv@e + (np.eye(7)-inv@J)@(.02*(self.home-q))
            q+=dq*min(1.,.15/(np.max(np.abs(dq))+1e-12))
            q=np.clip(q,self.limits[:,0]+.01,self.limits[:,1]-.01)
        return q,np.linalg.norm(ep),np.linalg.norm(er)
    def step(self,q,grip=-1,base=None,torso=0):
        a=np.zeros(13); a[:7]=q; a[7]=grip; a[12]=-1; a[11]=torso
        if base is not None:a[8:11]=base
        return self.s.step(a)
    def hold(self,n=10,grip=-1):
        q=self.s.targets[:7].copy()
        for _ in range(n):self.step(q,grip)
    def move(self,p,R=None,n=40,grip=-1,settle=8,verbose=True):
