from controller import Controller as BaseController
import numpy as np
from scipy.spatial.transform import Rotation
class Controller(BaseController):
 def move(self,p,R=None,n=40,grip=-1,settle=8,verbose=True):
  R=self.rot() if R is None else R
  start=self.pos();startR=self.rot();p=np.asarray(p)
  delta=Rotation.from_matrix(R@startR.T).as_rotvec()
  q=self.s.data.qpos[self.qids].copy(); progress=0.;last=None;stable=0
  for t in range(max(60,4*n)):
   if last is None or np.linalg.norm(self.pos()-last)<getattr(self,'tracking_limit',.015):progress=min(1.,progress+1/n)
   u=progress*progress*(3-2*progress)
   pt=start+(p-start)*u;Rt=Rotation.from_rotvec(delta*u).as_matrix()@startR
   q,ep,er=self.ik(pt,Rt,q)
   measured=self.s.data.qpos[self.qids];cap=getattr(self,'joint_step',.1)
   command=np.clip(q,measured-cap,measured+cap)
   self.step(command,grip);last=pt
   if progress>=1:
    stable=stable+1 if np.linalg.norm(self.pos()-p)<.0015 and np.linalg.norm(Rotation.from_matrix(R@self.rot().T).as_rotvec())<.01 else 0
    if stable>=3:break
  self.hold(settle,grip)
  if verbose:print('move',len(self.s.actions),'eef',self.pos().round(4),'target',p.round(4),'progress',progress,'IK',ep,er,'success',self.s.success,flush=True)
